package demo.brain;

import java.util.*;
import org.springframework.stereotype.Service;
import static demo.brain.TwinEngine.*;

@Service
public class TwinLab {
 private final java.util.concurrent.ExecutorService evaluationWorker=java.util.concurrent.Executors.newSingleThreadExecutor();
 private final java.util.concurrent.atomic.AtomicBoolean evaluating=new java.util.concurrent.atomic.AtomicBoolean();
 @org.springframework.beans.factory.annotation.Autowired(required=false) private BackgroundActivity activity;
 @jakarta.annotation.PreDestroy void shutdown(){evaluationWorker.shutdownNow();}
 @org.springframework.context.event.EventListener(org.springframework.boot.context.event.ApplicationReadyEvent.class)
 public void recoverInterrupted(){for(var row:s.db.queryForList("SELECT * FROM twin_runs WHERE status IN ('ANALYZING','GENERATING')")){var run=document(row);String old=run.get("status").toString();run.put("status",old.equals("ANALYZING")?"FAULTED":"ANALYZED");event(run,"INTERRUPTED","서버 재시작으로 AI 작업이 중단되었습니다. 직접 재실행하세요.",Map.of());s.db.update("UPDATE twin_runs SET status=?,document_json=?,version=version+1 WHERE id=? AND version=?",run.get("status"),s.encode(run),run.get("id"),run.get("version"));}for(var row:s.db.queryForList("SELECT id,result_json FROM twin_evaluations WHERE status='RUNNING'")){var report=map(s.decode(row.get("result_json")));if("RUNNING".equals(report.get("status"))){report.put("status","INTERRUPTED");report.put("error","서버 재시작으로 중단됨. 완료된 평가로 표시하지 않습니다.");saveEvaluation(row.get("id").toString(),report);}}}
 public Map<String,Object> evaluate(String mode,String provider){
  Access.admin();mode(Map.of("mode",mode));provider(Map.of("provider",provider));
  if(!evaluating.compareAndSet(false,true))throw new IllegalStateException("평가가 이미 실행 중입니다.");
  String id=Store.id("TEVAL-"),owner=Access.actor();var pending=Map.<String,Object>of("id",id,"status","RUNNING","mode",mode,"sampleCount",6,"completed",0,"rows",List.of());
  try{s.db.update("INSERT INTO twin_evaluations(id,owner_id,result_json,created_at,status,completed) VALUES (?,?,?,?,'RUNNING',0)",id,owner,s.encode(pending),Store.now());
   evaluationWorker.submit(()->{if(activity!=null)activity.jobStarted();try{executeEvaluation(mode,provider,owner,id);}catch(Exception e){saveEvaluation(id,Map.of("id",id,"status","FAILED","error",Objects.toString(e.getMessage(),"평가 오류")));}finally{evaluating.set(false);if(activity!=null)activity.jobFinished();}});
  }catch(RuntimeException e){evaluating.set(false);throw e;}return pending;
 }

 private final Store s;private final TwinAgents agents;
 public TwinLab(Store s,TwinAgents agents){this.s=s;this.agents=agents;}
 public Map<String,Object> catalog(){return Map.of("modelVersion",VERSION,"scope","Synthetic Data 기반 시뮬레이션 모델 · 실제 운영 복제 아님","baseline",initial(42),"faultTypes",FaultType.values(),"allowedActions",ActionType.values(),"assumptions",List.of("분석용 합성 모델이며 실측 SLA·성공 확률이 아닙니다.","의존 호출은 가용성 곱, 이중화 풀은 가용 용량/요구량으로 계산합니다.","비동기 복제 지연 ≤5초, fencing·승격·연결 전환 조건을 검증합니다.","전략 비교 중 장애 만료 시각은 고정해 자연 회복을 전략 효과로 계산하지 않습니다.","예상 복구 시간·위험 점수는 버전이 고정된 규칙 추정치입니다."),"scoreWeights",Map.of("SPEED",List.of(.4,.35,.1,.1,.05),"STABILITY",List.of(.1,.45,.3,.1,.05),"DATA",List.of(.1,.25,.2,.4,.05)),"scoreOrder",List.of("속도=max(0,100-초/2)","가용성","안정성=100-잔여위험","데이터=100-데이터위험","단순성=max(0,100-액션수×10)"));}
 public List<Map<String,Object>> list(){return s.db.queryForList("SELECT id,status,version,created_at,updated_at FROM twin_runs WHERE owner_id=? ORDER BY created_at DESC LIMIT 50",Access.actor());}
 @SuppressWarnings("unchecked") private Map<String,Object> document(Map<String,Object> row){var d=(Map<String,Object>)s.decode(row.get("document_json"));d.put("version",((Number)row.get("version")).intValue());d.put("status",row.get("status"));return d;}
 public Map<String,Object> get(String id){var row=s.one("SELECT * FROM twin_runs WHERE id=?",id);if(!Access.current().admin()&&!row.get("owner_id").equals(Access.actor()))throw Access.denied();return document(row);}
 public Map<String,Object> create(long seed){String id=Store.id("TWIN-");var d=new LinkedHashMap<String,Object>();d.put("id",id);d.put("seed",seed);d.put("modelVersion",VERSION);d.put("fictional",true);d.put("status","NORMAL");d.put("baseline",initial(seed));d.put("current",initial(seed));d.put("events",new ArrayList<>());d.put("approvals",new ArrayList<>());d.put("objective","STABILITY");event(d,"INFRA","정상 가상 인프라 생성",Map.of("seed",seed));s.db.update("INSERT INTO twin_runs(id,owner_id,version,status,document_json,created_at,updated_at) VALUES (?,?,0,?,?,?,?)",id,Access.actor(),"NORMAL",s.encode(d),Store.now(),Store.now());return get(id);}
 public Snapshot snapshot(Map<String,Object> d,String key){return s.json.convertValue(d.get(key),Snapshot.class);}
 @SuppressWarnings("unchecked") private void event(Map<String,Object> d,String stage,String message,Object evidence){((List<Object>)d.get("events")).add(Map.of("sequence",((List<?>)d.get("events")).size()+1,"stage",stage,"message",message,"at",java.time.Instant.now().toString(),"evidence",evidence));}
 private void state(Map<String,Object> d,String... allowed){if(!List.of(allowed).contains(d.get("status")))throw new IllegalStateException("현재 상태에서 실행할 수 없습니다: "+d.get("status"));}
 private Map<String,Object> save(Map<String,Object> d,int expected){String id=d.get("id").toString();return s.tx(()->{if(s.db.update("UPDATE twin_runs SET document_json=?,status=?,version=version+1,updated_at=? WHERE id=? AND version=?",s.encode(d),d.get("status"),Store.now(),id,expected)!=1)throw new IllegalStateException("상태가 변경되었습니다. 최신 실행을 다시 불러오세요.");s.audit(null,Access.actor(),"TWIN_"+d.get("status"),Map.of("runId",id,"version",expected+1));return get(id);});}
 public Map<String,Object> command(String id,String op,Map<String,Object> body){
  var d=get(id);int version=((Number)d.get("version")).intValue();if(!(body.get("version") instanceof Number n)||n.intValue()!=version)throw new IllegalStateException("최신 버전이 필요합니다.");
  if(!op.equals("request"))Access.admin();
  switch(op){
   case "inject"->{state(d,"NORMAL","FAULTED");List<Fault> faults=s.json.convertValue(body.get("faults"),s.json.getTypeFactory().constructCollectionType(List.class,Fault.class));var snap=inject(snapshot(d,"current"),faults);d.put("current",snap);d.put("faultSnapshot",snap);d.put("propagation",propagation(snap));d.put("status","FAULTED");event(d,"CHAOS","장애 주입·의존성 전파 계산",faults);}
   case "advance"->{state(d,"FAULTED");var snap=advance(snapshot(d,"current"),((Number)body.getOrDefault("seconds",10)).intValue());d.put("current",snap);d.put("faultSnapshot",snap);d.put("propagation",propagation(snap));event(d,"CLOCK","가상 시간 이동",Map.of("time",snap.time()));}
   case "stop","reset"->{var snap=op.equals("reset")?initial(((Number)d.get("seed")).longValue()):stop(snapshot(d,"current"));d.put("current",snap);d.put("status","NORMAL");for(String key:List.of("propagation","faultSnapshot","analysis","generation","strategies","results","selectedStrategy","recommendation"))d.remove(key);event(d,"RESTORE",op.equals("reset")?"동일 시드 초기 상태 복원":"장애 주입 종료",Map.of("snapshot",snap));}
   case "analyze"->{state(d,"FAULTED");String mode=mode(body),provider=provider(body);d.put("status","ANALYZING");event(d,"DIAGNOSIS","원인 분석 시작",Map.of("mode",mode,"provider",provider));d=save(d,version);version++;
    var analysis=agents.analyze(snapshot(d,"faultSnapshot"),mode,provider);d.put("analysis",analysis);d.put("mode",mode);d.put("provider",provider);d.put("status","ANALYZED");event(d,"DIAGNOSIS","관측 기반 원인 후보·영향 분석 완료",analysis);}
   case "strategies"->{state(d,"ANALYZED");d.put("status","GENERATING");event(d,"STRATEGY","복구 전략 생성 시작",Map.of());d=save(d,version);version++;
    var generation=agents.generate(snapshot(d,"faultSnapshot"),d.get("mode").toString(),map(d.get("analysis")));d.put("generation",generation);d.put("strategies",generation.get("strategies"));d.put("status","PLANNED");event(d,"POLICY","복구 전략·화이트리스트 검증 완료",generation);}
   case "simulate"->{state(d,"PLANNED","COMPARED");var strategies=strategies(d);var input=snapshot(d,"faultSnapshot");var results=strategies.stream().map(st->simulate(input,st)).toList();d.put("results",results);d.put("status","COMPARED");recommend(d,Objects.toString(body.getOrDefault("objective","STABILITY")));event(d,"SIMULATION","동일 장애 스냅샷에서 독립 시뮬레이션 완료",Map.of("results",results));}
   case "recommend"->{state(d,"COMPARED");recommend(d,Objects.toString(body.get("objective")));event(d,"EVALUATOR","평가 가중치 변경",d.get("recommendation"));}
   case "request"->{state(d,"COMPARED");String selected=Objects.toString(body.get("strategyId"),"");result(d,selected);d.put("selectedStrategy",selected);d.put("status","WAITING_APPROVAL");event(d,"APPROVAL","가상 복구 승인 요청 · 자동 승인은 수행하지 않음",Map.of("strategyId",selected,"actor",Access.actor()));}
   case "decision"->{state(d,"WAITING_APPROVAL");String reason=Objects.toString(body.get("reason"),"").strip();Harness.text(reason,1000,"승인·반려 사유");if(!(body.get("approved") instanceof Boolean))throw new IllegalArgumentException("승인 여부 필요");boolean approved=Boolean.TRUE.equals(body.get("approved"));var r=result(d,d.get("selectedStrategy").toString());if(approved&&r.outcome().equals("FAILED"))throw new IllegalStateException("실패한 전략은 확정할 수 없습니다.");d.put("status",approved?"APPROVED":"REJECTED");if(approved)d.put("current",r.after());var audit=Map.of("approved",approved,"reason",reason,"actor",Access.actor(),"at",java.time.Instant.now().toString(),"strategyId",r.strategyId());((List<Object>)d.get("approvals")).add(audit);event(d,"REPORT",approved?"승인한 가상 결과 확정 · 실제 시스템 변경 없음":"전략 반려",audit);}
   default->throw new IllegalArgumentException("알 수 없는 Lab 작업");
  }
  return save(d,version);
 }
 private static String mode(Map<String,Object> b){String m=Objects.toString(b.getOrDefault("mode","DEMO"));if(!List.of("DEMO","REAL").contains(m))throw new IllegalArgumentException("모드 오류");return m;}
 private static String provider(Map<String,Object> b){String p=Objects.toString(b.getOrDefault("provider","LOCAL"));if(!List.of("LOCAL","TYPESAFE").contains(p))throw new IllegalArgumentException("Provider 오류");return p;}
 @SuppressWarnings("unchecked") private static Map<String,Object> map(Object o){return (Map<String,Object>)o;}
 public List<Strategy> strategies(Map<String,Object> d){return s.json.convertValue(d.get("strategies"),s.json.getTypeFactory().constructCollectionType(List.class,Strategy.class));}
 private List<Result> results(Map<String,Object> d){return s.json.convertValue(d.get("results"),s.json.getTypeFactory().constructCollectionType(List.class,Result.class));}
 private Result result(Map<String,Object>d,String id){return results(d).stream().filter(r->r.strategyId().equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("검증되지 않은 전략"));}
 private void recommend(Map<String,Object>d,String objective){var ranking=results(d).stream().map(r->Map.<String,Object>of("strategyId",r.strategyId(),"score",score(r,objective),"outcome",r.outcome())).sorted(Comparator.comparingDouble((Map<String,Object> r)->((Number)r.get("score")).doubleValue()).reversed()).toList();var candidate=ranking.stream().filter(r->!r.get("outcome").equals("FAILED")).findFirst();d.put("objective",objective);d.put("recommendation",Map.of("strategyId",candidate.map(r->r.get("strategyId")).orElse(""),"ranking",ranking,"reason",candidate.isPresent()?"선택 가중치의 시뮬레이션 점수가 가장 높은 비실패 전략 · 성공 확률 아님":"추천 가능한 비실패 전략 없음"));}
 private Map<String,Object> executeEvaluation(String mode,String provider,String owner,String evaluationId){var rows=new ArrayList<Map<String,Object>>();int correct=0,actual=0,success=0,unsafe=0;long elapsed=0;
  var cases=List.of(new Fault(FaultType.DB_PRIMARY,"db-primary",1,300,0),new Fault(FaultType.REDIS_FAILURE,"redis",1,300,0),new Fault(FaultType.CPU_OVERLOAD,"app-1",1,300,0),new Fault(FaultType.MEMORY_PRESSURE,"app-2",1,300,0),new Fault(FaultType.QUEUE_FAILURE,"mq",1,300,0),new Fault(FaultType.NETWORK_LATENCY,"gateway",1,300,0));
  for(var f:cases){var snapshot=inject(initial(42),List.of(f));var a=agents.analyze(snapshot,mode,provider);boolean isAi=Boolean.TRUE.equals(a.get("actualModelCall"));if(isAi)actual++;boolean hit=a.get("cause").equals(f.type().name());if(hit)correct++;elapsed+=((Number)a.get("latencyMs")).longValue();var g=agents.generate(snapshot,mode,a);List<Strategy> plans=s.json.convertValue(g.get("strategies"),s.json.getTypeFactory().constructCollectionType(List.class,Strategy.class));List<Strategy> typed=plans;var results=typed.stream().map(st->simulate(snapshot,st)).toList();success+=(int)results.stream().filter(r->r.outcome().equals("SUCCESS")).count();unsafe+=((Number)g.get("rejectedResponses")).intValue();rows.add(Map.of("faultType",f.type(),"expected",f.type().name(),"analysis",a,"correct",hit,"generation",g,"results",results));saveEvaluation(evaluationId,Map.of("id",evaluationId,"status","RUNNING","mode",mode,"completed",rows.size(),"sampleCount",cases.size(),"rows",rows));}
  var report=new LinkedHashMap<String,Object>();report.put("id",evaluationId);report.put("status","COMPLETED");report.put("datasetVersion","synthetic-twin-six-v1");report.put("mode",mode);report.put("provider",provider);report.put("actualAiCount",actual);report.put("sampleCount",cases.size());report.put("correct",correct);report.put("actualAiCorrect",rows.stream().filter(r->Boolean.TRUE.equals(map(r.get("analysis")).get("actualModelCall"))&&Boolean.TRUE.equals(r.get("correct"))).count());report.put("meanAnalysisMs",elapsed/cases.size());report.put("simulationSuccesses",success);report.put("simulationCount",rows.stream().mapToInt(r->((List<?>)r.get("results")).size()).sum());report.put("rejectedStrategyResponses",unsafe);report.put("rows",rows);
  long proposed=rows.stream().mapToLong(r->((Number)map(r.get("generation")).get("proposedActions")).longValue()).sum(),dangerous=rows.stream().mapToLong(r->((Number)map(r.get("generation")).get("unsafeActions")).longValue()).sum();
  report.put("proposedActions",proposed);report.put("unsafeActions",dangerous);report.put("unsafeProposalRate",proposed==0?null:100.0*dangerous/proposed);
  report.put("strategySuitability",Map.of("improved",rows.stream().flatMap(r->((List<Result>)r.get("results")).stream()).filter(r->!r.outcome().equals("FAILED")).count(),"total",rows.stream().mapToInt(r->((List<?>)r.get("results")).size()).sum(),"criterion","가용성 개선 또는 서비스 성공 기준 달성"));
  report.put("agentMetrics",Map.of("diagnosis",Map.of("validModelResults",actual,"attempts",mode.equals("REAL")?cases.size():0),"strategy",Map.of("validModelResults",rows.stream().filter(r->"HERMES_AGENT".equals(map(r.get("generation")).get("source"))).count(),"attempts",mode.equals("REAL")?cases.size():0),"simulation",Map.of("computed",rows.stream().mapToInt(r->((List<?>)r.get("results")).size()).sum())));
  report.put("limits","6개 합성 시나리오의 관측 기반 평가. 실제 운영 일반화 성능 아님. 생성 거부에는 통신·스키마 오류도 포함되며 위험 제안 비율로 대체하지 않음.");saveEvaluation(evaluationId,report);return report;
 }
 private void saveEvaluation(String id,Map<String,Object> report){
  int completed="COMPLETED".equals(report.get("status"))?6:((Number)report.getOrDefault("completed",0)).intValue();
  s.db.update("UPDATE twin_evaluations SET status=?,completed=?,result_json=? WHERE id=?",report.get("status"),completed,s.encode(report),id);
 }
 public List<Map<String,Object>> evaluations(){return s.db.queryForList("SELECT id,status,completed,6 AS sample_count FROM twin_evaluations WHERE owner_id=? ORDER BY created_at DESC LIMIT 10",Access.actor()).stream().map(r->Map.<String,Object>of("id",r.get("id"),"status",r.get("status"),"completed",r.get("completed"),"sampleCount",r.get("sample_count"))).toList();}
 public Object evaluation(String id){Access.admin();return s.decode(s.one("SELECT result_json FROM twin_evaluations WHERE id=? AND owner_id=?",id,Access.actor()).get("result_json"));}
}
